import numpy as np
import scipy.stats as st
nan = float('nan')
inf = float('inf')

def close(x, ref, rtol: float = 1e-8, atol: float = 1e-12) -> bool:
    a = np.asarray(x).astype(float).ravel()
    r = np.asarray(ref).astype(float).ravel()
    if a.shape != r.shape:
        print('shape', a.shape, r.shape)
        return False
    ok = True
    for i in range(a.shape[0]):
        u = float(a[i])
        v = float(r[i])
        if not (abs(u - v) <= atol + rtol * abs(v) or (u != u and v != v) or u == v):
            print('mismatch', i, u, v)
            ok = False
    return ok

@test
def test_fisher():
    d = st.nchypergeom_fisher
    a = (140, 80, 60, 0.5)
    ks = [0.0, 7.0, 14.0, 21.0, 28.0, 35.0, 42.0, 49.0, 56.0]
    assert close(d.pmf(ks, *a), [1.2167117083764205e-31, 1.1662085305684744e-15, 1.9427178627693589e-07, 0.0046791164227673555, 0.13681968829542868, 0.01064431147099963, 2.4923700318018385e-06, 1.0598227763112596e-12, 1.335845137165613e-22], 1e-7)
    assert close(d.cdf(ks, *a), [1.2167117083764205e-31, 1.1953143604024077e-15, 2.2118875093323713e-07, 0.0071467442586283375, 0.50915770741617, 0.9927379371407138, 0.9999994519814455, 0.9999999999999237, 1.0], 1e-7)
    assert close(d.sf(ks, *a), [1.0, 0.9999999999999988, 0.999999778811249, 0.9928532557413716, 0.49084229258383005, 0.007262062859286211, 5.480185545359006e-07, 7.627232179174825e-14, 0.0], 1e-7)
    assert close(d.ppf([0.05, 0.3, 0.5, 0.7, 0.95], *a), [24.0, 27.0, 28.0, 30.0, 33.0])
    assert close([d.mean(*a), d.var(*a)], [28.44642744936175, 8.300922457539917], 1e-7)
    assert close(d.rvs(*a, size=6, random_state=np.random.RandomState(1234)), [25.0, 24.0, 30.0, 22.0, 28.0, 27.0])
    assert close(d.rvs(*a, size=6, random_state=np.random.default_rng(42)), [29.0, 27.0, 26.0, 31.0, 25.0, 32.0])

