    a = (140, 80, 60, 0.5)
    ks = [0.0, 7.0, 14.0, 21.0, 28.0, 35.0, 42.0, 49.0, 56.0]
    assert close(d.pmf(ks, *a), [0.0, 1.2589201280763544e-13, 4.047251381214528e-06, 0.019785309216959403, 0.12348672147900408, 0.0021488996149980413, 1.1757356547383755e-07, 1.12814605688037e-14, 0.0], 1e-7)
    assert close(d.cdf(ks, *a), [0.0, 1.2927005458353896e-13, 4.775604321621362e-06, 0.034311891953254035, 0.7427110145070387, 0.998921473453203, 0.9999999795944192, 0.9999999999759761, 0.9999999999759759], 1e-7)
