@test
def test_poisson_binom():
    p = [0.1, 0.35, 0.6, 0.8, 0.25, 0.9]
    ks = [-1, 0, 1, 2, 3, 4, 5, 6, 7]
    assert close(st.poisson_binom.pmf(ks, p), [0.0, 0.0035099999999999992, 0.054345, 0.24580000000000002, 0.39515000000000006, 0.24115, 0.056264999999999996, 0.00378, 0.0])
    assert close(st.poisson_binom.cdf(ks, p), [0.0, 0.0035099999999999992, 0.057855, 0.303655, 0.6988050000000001, 0.9399550000000001, 0.9962200000000001, 1.0, 1.0])
    assert close(st.poisson_binom.sf(ks, p), [1.0, 0.99649, 0.942145, 0.696345, 0.3011949999999999, 0.060044999999999904, 0.0037799999999998946, 0.0, 0.0])
    assert close(st.poisson_binom.ppf([0.05, 0.5, 0.95], p), [1.0, 3.0, 5.0])
    assert close(st.poisson_binom.stats(p, moments='mv'), [2.9999999999999996, 0.995])
    assert close(st.poisson_binom(p, loc=2).pmf([2, 3, 4]), [0.0035099999999999992, 0.054345, 0.24580000000000002])
    assert close(st.poisson_binom.rvs(p, size=5, random_state=np.random.RandomState(7)), [5.0, 3.0, 2.0, 2.0, 4.0])
